WITH remaining_keys AS (SELECT event_type, id FROM web_events INTERSECT ALL SELECT event_type, id FROM web_events WHERE HOUR(event_time) BETWEEN 8 AND 11), reconciled AS (SELECT s.* FROM web_events s INNER JOIN remaining_keys k ON s.event_type = k.event_type AND s.id = k.id) SELECT id, session_id, event_type, page, event_time, duration_sec FROM reconciled ORDER BY session_id ASC NULLS FIRST;
